window.I18N_EN_PATTERNS = (function () {
  const N = '([\\d٠-٩][\\d٠-٩,.]*)';
  const T = (s) => (window.t ? window.t(s) : s);
  const lec = (n) => (Number(String(n).replace(/,/g, '')) === 1 ? 'lecture' : 'lectures');
  return [
    [new RegExp('^' + N + ' (?:محاضرة|محاضرات)$'), (m, n) => `${n} ${lec(n)}`],
    [new RegExp('^' + N + ' محاضرة مسجلة \\(حوالي (.+)\\)$'), (m, n, d) => `${n} recorded ${lec(n)} (about ${T(d)})`],
    [new RegExp('^' + N + ' (?:محاضرة|محاضرات) · (.+)$'), (m, n, d) => `${n} ${lec(n)} · ${T(d)}`],
    [new RegExp('^' + N + ' دقيقة$'), (m, n) => `${n} min`],
    [new RegExp('^' + N + ' مقعد$'), (m, n) => `${n} seats`],
    [new RegExp('^' + N + ' (?:برنامج|برامج)$'), (m, n) => `${n} programme${Number(n) === 1 ? '' : 's'}`],
    [/^يبدأ (.+)$/, (m, d) => `Starts ${d}`],
    [/^من فضلك املأ: (.+)$/, (m, x) => `Please fill in: ${x}`],
    [new RegExp('^' + N + ' محاضر$'), (m, n) => `${n} instructor${Number(String(n).replace(/,/g, '')) === 1 ? '' : 's'}`],
    [new RegExp('^' + N + ' ساعة(?: و' + N + ' دقيقة)?$'), (m, h, mi) => `${h} h${mi ? ' ' + mi + ' min' : ''}`],
    [new RegExp('^' + N + ' ج\\.م$'), (m, n) => `EGP ${n}`],
    [new RegExp('^([−\\-·]) ' + N + ' ج\\.م$'), (m, s, n) => `${s} EGP ${n}`],
    [new RegExp('^منها ' + N + ' ج\\.م رسوم البوابة$'), (m, n) => `incl. EGP ${n} gateway fee`],
    [new RegExp('^خصم ' + N + ' ج\\.م$'), (m, n) => `discount EGP ${n}`],
    [new RegExp('^وفر ' + N + '٪$'), (m, n) => `Save ${n}%`],
    [new RegExp('^صلاحية ' + N + ' (?:أشهر|شهرًا|شهر)$'), (m, n) => `Valid for ${n} months`],
    [new RegExp('^السعر السابق ' + N + ' · (.+)$'), (m, n, r) => `Was EGP ${n} · ${T(r)}`],
    [new RegExp('^تبدأ من ' + N + ' ج\\.م / (.+)$'), (m, n, r) => `From EGP ${n} / ${/^\d+ أشهر$/.test(r) ? r.replace(' أشهر', ' months') : T(r)}`],
    [new RegExp('^أنهيت ' + N + ' من ' + N + ' (?:محاضرة|محاضرات)(.*)$'), (m, a, b, rest) => `Completed ${a} of ${b} lectures` + (rest ? ' ' + T(rest.trim()) : '')],
    [/^· الشهادة تُفتح عند إتمام الدورة$/, () => '· The certificate unlocks when you finish the course'],
    [/^· التالية: (.+)$/, (m, x) => `· Next: ${x}`],
    [new RegExp('^' + N + ' من ' + N + ' (?:محاضرة|محاضرات)$'), (m, a, b) => `${a} of ${b} lectures`],
    [new RegExp('^' + N + ' من ' + N + ' دورة$'), (m, a, b) => `${a} of ${b} courses`],
    [new RegExp('^المحاضرة ' + N + ' من ' + N + '$'), (m, a, b) => `Lecture ${a} of ${b}`],
    [new RegExp('^الخطوة ' + N + ' من ' + N + '$'), (m, a, b) => `Step ${a} of ${b}`],
    [/^أهلاً (.+?) · تابع من حيث توقفت$/, (m, n) => `Hi ${n === 'بك' ? 'there' : n} · pick up where you left off`],
    [/^أهلاً (.+)$/, (m, n) => `Hi ${n === 'بك' ? 'there' : n}`],
    [/^ينتهي في (.+)$/, (m, d) => `Ends on ${d}`],
    [/^· تنتهي في$/, () => '· ends on'],
    [/^صدرت في (.+)$/, (m, d) => `Issued on ${d}`],
    [/^بتاريخ (.+?) · رقم الشهادة$/, (m, d) => `on ${d} · Certificate no.`],
    [/^بتاريخ (.+?)\.?$/, (m, d) => `on ${d}.`],
    [/^الباقة التالية تبدأ (.+)$/, (m, d) => `next plan starts ${d}`],
    [new RegExp('^حوّل ' + N + ' ج\\.م عبر إنستاباي إلى:$'), (m, n) => `Transfer EGP ${n} via InstaPay to:`],
    [new RegExp('^حوّل ' + N + ' ج\\.م على محفظة فودافون كاش رقم:$'), (m, n) => `Transfer EGP ${n} to Vodafone Cash wallet:`],
    [new RegExp('^تم تطبيق الكود: خصم ' + N + ' ج\\.م( \\(مجاني بالكامل\\))?$'), (m, n, f) => `Code applied: EGP ${n} off${f ? ' (completely free)' : ''}`],
    [/^اشتراك: (.+)$/, (m, x) => `Subscription: ${T(x)}`],
    [/^دورة تفاعلية: (.+)$/, (m, x) => `Interactive course: ${x}`],
    [new RegExp('^اشتراك ' + N + ' أشهر$'), (m, n) => `${n}-month plan`],
    [new RegExp('^' + N + ' شهر$'), (m, n) => `${n} month(s)`],
    [new RegExp('^' + N + ' مشاهدة × ' + N + ' ج\\.م$'), (m, a, b) => `${a} views × EGP ${b}`],
    [new RegExp('^' + N + ' دورة$'), (m, n) => `${n} courses`],
    [/^مستوى (.+?) · بالعربية$/, (m, l) => `${T(l)} level · in Arabic`],
    [/^(.+) \| Biosyn Egypt$/, (m, x) => { const r = T(x); return r === x ? null : `${r} | Biosyn Egypt`; }],
    [/^(.+)، (\d{1,2}:\d{2}) ([صم])$/, (m, d, t, ap) => `${d}, ${t} ${ap === 'ص' ? 'AM' : 'PM'}`],
    [/^أكثر من (\d+)$/, (m, n) => `More than ${n}`],
    [/^(.+) (←|→)$/, (m, x, a) => { const r = T(x); return r === x ? null : `${r} →`; }],
  ];
})();
